INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (247, 41, 1, 'يَتْفُلُ عليه، ويقرأ بأمِّ القرآن: (الفاتحة).', 0, 'ما يقرأ على الملدوغ. (ص150)', '', '', 'يتفل عليه ويقرأ بأم القرآن الفاتحة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (248, 41, 2, 'أُعيذُكُم بكلماتِ اللهِ التامَّةِ، من كلِّ شيطانٍ وهامَّةٍ، ومن كلِّ عينٍ لامَّةٍ', 1, 'ما يُعَوِّذُ به الصبيان وغيرَهُمْ. (ص150)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1599, 41, 3, 'من ابْتُلِيَ بوسوسة الشيطان بقوله مثلًا: «مَنْ خَلَقَ اللهَ؟»، فيجب عليه:', 0, 'ما يقول من بُلِيَ بالوسوسة. (ص151–155)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1600, 41, 4, 'أن ينتهيَ عن الانسياق مع وسوسَتِه، وينصرِفَ عن مجادلته، إلى إجابته بما يلي:', 0, 'ما يقول من بُلِيَ بالوسوسة. (ص155)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (249, 41, 5, 'آمنتُ باللهِ ورسُلِه', 1, 'ما يقول من بُلِيَ بالوسوسة. (ص156)', '', '', 'آمنت بالله ورسله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (250, 41, 6, 'هو الأولُ والآخِرُ، والظاهرُ والباطنُ، وهو بكلِّ شيءٍ عليم', 1, 'ما يقول من بُلِيَ بالوسوسة. (ص156)', '', '', 'هو الأول والآخر والظاهر والباطن وهو بكل شيء عليم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (251, 41, 7, 'اللهُ أَحَدٌ، اللهُ الصَّمَدُ، لم يَلِدْ، ولم يُولَدْ، ولم يكن له كُفُوًا أَحَدٌ', 1, 'ما يقول من بُلِيَ بالوسوسة. (ص156)', '', '', 'الله أحد الله الصمد لم يلد ولم يولد ولم يكن له كفوا أحد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1601, 41, 8, 'ثُمَّ يَتْفُلُ عن يسارِه ثلاثًا، ويقول:', 0, 'ما يقول من بُلِيَ بالوسوسة. (ص156)', '', '', 'ثم يتفل عن يساره ثلاثا ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (252, 41, 9, 'أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ، ومن فِتْنَتِهِ', 1, 'ما يقول من بُلِيَ بالوسوسة. (ص156)', '', '', 'أعوذ بالله السميع العليم من الشيطان الرجيم ومن فتنته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1602, 41, 10, 'يتعوذ بالله منه، ويَتْفُلُ عن يسارِه ثلاثًا.', 0, 'ما يقول إذا حالَ الشيطانُ بينَه وبينَ صلاتِه وقراءتِه يُلَبِّسُها عليه. (ص157)', '', '', 'يتعوذ بالله منه ويتفل عن يساره ثلاثا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (253, 42, 1, 'رَبِّ إِنِّي ﴿ مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ ﴾', 1, 'ما يقوله المريض. [الأنبياء: ٨٣] (ص157)', '', '', 'رب إني ﴿ مسني ٱلضر وأنت أرۡحم ٱلرحمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1603, 42, 2, 'يجمعُ كَفَّيْهِ، ويقرأُ فيهما السورَ المعوذاتِ:', 0, 'ما يقوله المريض. (ص157)', '', '', 'يجمع كفيه ويقرأ فيهما السور المعوذات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (254, 42, 3, '﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، و﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾، ويَنْفُثُ فيهما، ثم يمسَحُ بهما ما استطاعَ من جَسَدِه: يبدأ بهما على رأسِهِ ووجهِهِ، وما أقبلَ من جَسَدِه، يفعلُ ذلك كُلَّه ثلاثَ مرَّاتٍ، فإن لم يَسْتَطِعْ، فلْيَفْعَلْ به ذلك غيرُهُ', 1, 'ما يقوله المريض. (ص157–158)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1604, 42, 4, 'ويضعُ المريضُ يَدَهُ على الذي تألَّمَ مِنْ جَسَدِه.', 0, 'ما يقوله المريض. (ص158)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1605, 42, 5, 'ويقول:', 0, 'ما يقوله المريض. (ص158)', '', '', 'ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (255, 42, 6, 'باسمِ اللهِ', 3, 'ما يقوله المريض. (ص158)', '', '', 'باسم الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1606, 42, 7, 'ثم يقول:', 0, 'ما يقوله المريض. (ص158)', '', '', 'ثم يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (256, 42, 8, 'أعوذُ بعزَّةِ اللهِ وقُدرتِهِ من شرِّ ما أَجِدُ وأُحاذِرُ', 7, 'ما يقوله المريض. (ص158)', '', '', 'أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1607, 42, 9, 'ويقول المريض:', 0, 'ما يقوله المريض. (ص158)', '', '', 'ويقول المريض', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (257, 42, 10, 'لا إلهَ إلا اللهُ، واللهُ أكبرُ، لا إلهَ إلا اللهُ وحدَهُ، لا إلهَ إلا اللهُ لا شريكَ له، لا إلهَ إلا اللهُ، له الملكُ، وله الحمدُ، لا إلهَ إلا اللهُ، ولا حولَ ولا قوةَ إلا باللهِ', 1, 'ما يقوله المريض. (ص158–159)', '', '', 'لا إله إلا الله والله أكبر لا إله إلا الله وحده لا إله إلا الله لا شريك له لا إله إلا الله له الملك وله الحمد لا إله إلا الله ولا حول ولا قوة إلا بالله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1608, 42, 11, 'ويقول:', 0, 'ما يقوله المريض. (ص159)', '', '', 'ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (258, 42, 12, 'اللهُ ربِّي، لا شريكَ له', 1, 'ما يقوله المريض. (ص159)', '', '', 'الله ربي لا شريك له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (259, 42, 13, 'لا إلهَ إلا أنتَ، سبحانَكَ، إني كنتُ من الظالمين', 1, 'ما يقوله المريض. (ص159)', '', '', 'لا إله إلا أنت سبحانك إني كنت من الظالمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (260, 42, 14, 'اللهم آتنا في الدنيا حَسَنَةً، وفي الآخرةِ حَسَنَةً، وَقِنا عذابَ النار', 1, 'ما يقوله المريض. (ص159)', '', '', 'اللهم آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1609, 42, 15, 'ولا يَتَمَنَّيَنَّ الموتَ لِضُرٍّ ونحوِه، فإن خافَ على دينِه لفسادِ الزمان ونحو ذلك، قال:', 0, 'ما يقوله المريض. (ص159)', '', '', 'ولا يتمنين الموت لضر ونحوه فإن خاف على دينه لفساد الزمان ونحو ذلك قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (975, 42, 16, 'اللهمَّ أَحْيِني ما كانتِ الحياةُ خيرًا لي، وتَوَفَّني إذا كانتِ الوفاةُ خيرًا لي', 1, 'ما يقوله المريض. (ص159)', '', '', 'اللهم أحيني ما كانت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1610, 42, 17, 'وَيُسْتَحَبُّ أن يَدْعُوَ بأن يكونَ مَوْتُهُ في المدينةِ النبويةِ المباركة، فقد كان من دُعاءِ عمرَ رضي الله عنه:', 0, 'ما يقوله المريض. (ص159)', '', '', 'ويستحب أن يدعو بأن يكون موته في المدينة النبوية المباركة فقد كان من دعاء عمر رضي الله عنه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (976, 42, 18, 'اللهمَّ ارزقني شهادةً في سبيلِكَ، واجعلْ موتي في بلدِ رسولِكَ صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ', 1, 'ما يقوله المريض. (ص159)', '', '', 'اللهم ارزقني شهادة في سبيلك واجعل موتي في بلد رسولك صلى الله عليه وآله وسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1611, 43, 1, 'إذا دخل الزائر على من يَعُودُه، قال:', 0, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)', '', '', 'إذا دخل الزائر على من يعوده قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (261, 43, 2, 'لا بأسَ طَهورٌ إن شاءَ اللهُ', 1, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)', '', '', 'لا بأس طهور إن شاء الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (262, 43, 3, 'اكشِفِ الباسَ، ربَّ النَّاسِ، إلهَ الناسِ', 1, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)', '', '', 'اكشف الباس رب الناس إله الناس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (263, 43, 4, 'اللهمَّ اشفِ عبدَكَ، يَنْكَأْ لكَ عدوًّا، أو يَمْشِ لكَ إلى الصلاةِ', 1, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (264, 43, 5, 'اكشِفِ الباسَ، ربَّ الناسِ، لا يَكشِفُ الكَربَ غيرُكَ', 1, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)', '', '', 'اكشف الباس رب الناس لا يكشف الكرب غيرك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (265, 43, 6, 'اللهمَّ اشفِ «فلانًا»', 3, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص160)', '', '', 'اللهم اشف «فلانا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (266, 43, 7, 'امسَحِ الباسَ، ربَّ الناسِ، بيدِكَ الشِّفاءُ، لا كاشِفَ له إلا أنتَ', 1, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص161)', '', '', 'امسح الباس رب الناس بيدك الشفاء لا كاشف له إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (977, 43, 8, 'أسألُ اللهَ العظيمَ، ربَّ العرشِ العظيمِ أن يشفِيَكَ', 7, 'ما يُقال عند المريض، ويُقْرَأ عليه. (ص161)', '', '', 'أسأل الله العظيم رب العرش العظيم أن يشفيك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1612, 44, 1, 'ويضع الزائرُ سَبَّابَتَهُ بالأرضِ، ثُمَّ يرْفَعُها، ويقول:', 0, 'رقية المريض. (ص161)', '', '', 'ويضع الزائر سبابته بالأرض ثم يرفعها ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (267, 44, 2, 'باسمِ اللهِ، تُربَةُ أرضِنا، بِرِيقَةِ بعضِنا، يُشفى بهِ سَقيمُنا، بإذنِ ربِّنا', 1, 'رقية المريض. (ص161)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1613, 44, 3, 'وإذا أرادَ أن يرقيَهُ:', 0, 'رقية المريض. (ص162)', '', '', 'وإذا أراد أن يرقيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (268, 44, 4, 'يقرأ بفاتحة الكتاب، ويجمع بُزَاقه، ويَتْفُل، ويُعَوِّذُ المريضَ، فيمسحُ بيده اليمنى، ويقول:', 1, 'رقية المريض. (ص162)', '', '', 'يقرأ بفاتحة الكتاب ويجمع بزاقه ويتفل ويعوذ المريض فيمسح بيده اليمنى ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (269, 44, 5, 'اللهمَّ ربَّ الناسِ، أذهِبِ الباسَ، اشفِ أنتَ الشَّافي، لا شفاءَ إلا شفاؤُكَ، شفاءً لا يُغادِرُ سَقَمًا', 1, 'رقية المريض. (ص162)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1614, 44, 6, 'ويقول في الرقية:', 0, 'رقية المريض. (ص162)', '', '', 'ويقول في الرقية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (270, 44, 7, 'باسمِ اللهِ أُرقيكَ، من كلِّ شيءٍ يُؤذيكَ، من شرِّ كلِّ نفسٍ أو عينِ حاسدٍ، اللهُ يشفِيكَ، باسمِ اللهِ أُرقيكَ', 1, 'رقية المريض. (ص162)', '', '', 'باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد الله يشفيك باسم الله أرقيك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (978, 44, 8, 'باسمِ اللهِ يُبريكَ، ومن كلِّ داءٍ يشفيكَ، ومن شرِّ حاسدٍ إذا حسَدَ، وشرِّ كلِّ ذي عَينٍ', 1, 'رقية المريض. (ص162)', '', '', 'باسم الله يبريك ومن كل داء يشفيك ومن شر حاسد إذا حسد وشر كل ذي عين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1615, 45, 1, 'يقول لذويه:', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'يقول لذويه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (271, 45, 2, 'إنَّهُ قد حَضَرَ منِّي ما ليسَ اللهُ بتاركٍ مِنْهُ أحدًا لِمُوافاةِ يومِ القيامةِ', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'إنه قد حضر مني ما ليس الله بتارك منه أحدا لموافاة يوم القيامة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (272, 45, 3, 'ما أرى الأجلَ إلا اقتربَ، فاتقوا اللهَ واصبروا', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'ما أرى الأجل إلا اقترب فاتقوا الله واصبروا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1616, 45, 4, 'ويقول لهم:', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'ويقول لهم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (273, 45, 5, '﴿ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ﴾', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. [البقرة: ١٣٢] (ص163)', '', '', '﴿ إن ٱلله ٱصۡطفى لكم ٱلدين فلا تموتن إلا وأنتم مسۡلمون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1617, 45, 6, 'وليكُن هَمَّهُ ساعَتَئِذٍ أن يُوصيَهم بتوحيدِ الله عز وجل، والبراءةِ من الشرك، والثباتِ على الإسلام إلى المماتِ.', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'وليكن همه ساعتئذ أن يوصيهم بتوحيد الله عز وجل والبراءة من الشرك والثبات على الإسلام إلى الممات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1618, 45, 7, 'وعلى المحتَضَرِ أن ينهى عمَّا يتوقَّعُ حدوثَه من منكرٍ أو بدعةٍ، إذا آنس من ذويه ذلك.', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص163)', '', '', 'وعلى المحتضر أن ينهى عما يتوقع حدوثه من منكر أو بدعة إذا آنس من ذويه ذلك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1619, 45, 8, 'ويُكْثِرُ ذكرَ الله عز وجل، قال ﷺ: «خَيرُ العملِ: أن تُفَارِقَ الدُّنيا، ولسانُكَ رَطبٌ مِن ذِكرِ اللهِ».', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164)', '', '', 'ويكثر ذكر الله عز وجل قال «خير العمل أن تفارق الدنيا ولسانك رطب من ذكر الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1620, 45, 9, 'ومن الأذكار التي يتأكَّد الاهتمامُ بها في هذا الموطن:', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164)', '', '', 'ومن الأذكار التي يتأكد الاهتمام بها في هذا الموطن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (274, 45, 10, 'لا إلهَ إلا اللهُ، واللهُ أكبرُ، لا إلهَ إلا اللهُ وحدَهُ، لا إلهَ إلا اللهُ، لا شريكَ له، لا إلهَ إلا اللهُ، له الملكُ، وله الحمدُ، لا إلهَ إلا اللهُ، ولا حولَ ولا قوةَ إلا باللهِ', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164)', '', 'قال رسول الله ﷺ: «مَن رُزِقَهُنَّ عندَ مَوتِهِ لم تَمَسَّهُ النَّارُ».', 'لا إله إلا الله والله أكبر لا إله إلا الله وحده لا إله إلا الله لا شريك له لا إله إلا الله له الملك وله الحمد لا إله إلا الله ولا حول ولا قوة إلا بالله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1621, 45, 11, 'قراءة آية الكرسي دُبُرَ كُلِّ صلاةٍ.', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1622, 45, 12, 'قول سيد الاستغفار صباحًا ومساءً.', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1623, 45, 13, 'ويُحْسِنُ الظَّنَّ بالله عز وجل، ويُؤَمِّلُ منه كل الخير، وعلى الحاضرين أن يُعينُوه على ذلك بتذكيرِهِ بآياتِ وأحاديثِ الرَّجاءِ في رحمةِ الله، والطَّمَعِ في عفوه ومغفرته، وتذكيرِ المُحْتَضَرِ بأعمالِهِ الصالحةِ والثناء عليه بها.', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص164–165)', '', '', 'ويحسن الظن بالله عز وجل ويؤمل منه كل الخير وعلى الحاضرين أن يعينوه على ذلك بتذكيره بآيات وأحاديث الرجاء في رحمة الله والطمع في عفوه ومغفرته وتذكير المحتضر بأعماله الصالحة والثناء عليه بها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1624, 45, 14, 'فإذا حَضَرَهُ النزعُ، قال:', 0, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص165)', '', '', 'فإذا حضره النزع قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (275, 45, 15, 'لا إلهَ إلا اللهُ، إنَّ للموتِ سَكَراتٍ، اللهمَّ اغفرْ لي، وارحمني، وأَلْحِقْني بالرفيقِ الأعلى', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص165)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (276, 45, 16, 'ويَحْمَدُ اللهَ عزَّ وجلَّ', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص165)', '', '', 'ويحمد الله عز وجل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (277, 45, 17, 'ويُكْثِرُ من قولِ: «لا إله إلَّا الله»؛ ليكونَ آخِرَ كلامِهِ، أو يُلَقِّنُهُ إيَّاها بِرِفْقٍ مَنْ حَضَرَهُ', 1, 'ما يقول إذا استشعر حُضُورَ أَجَلِه. (ص165)', '', 'قال رسول الله ﷺ: «مَن كان آخرَ كلامِه (لا إله إلَّا اللهُ) دَخَلَ الجنَّةَ».', 'ويكثر من قول «لا إله إلا الله» ليكون آخر كلامه أو يلقنه إياها برفق من حضره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1625, 45, 18, 'يدعوه لأنْ يقولَ:', 0, 'ما يقول إذا حضر مُشْرِكًا يُحْتَضَر. (ص166)', '', '', 'يدعوه لأن يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (979, 45, 19, 'لا إلهَ إلا اللهُ، محمدٌ رسولُ اللهِ', 1, 'ما يقول إذا حضر مُشْرِكًا يُحْتَضَر. (ص166)', '', '', 'لا إله إلا الله محمد رسول الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1626, 45, 20, 'لا يَدْعُوَنَّ مَنْ حضره على نفسه إلا بخيرٍ، فإنَّ الملائكةَ يؤمِّنونَ على ما يقول.', 0, 'ما يقول بعد تغميض الميت. (ص166)', '', '', 'لا يدعون من حضره على نفسه إلا بخير فإن الملائكة يؤمنون على ما يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1627, 45, 21, 'يقول:', 0, 'ما يقول بعد تغميض الميت. (ص166)', '', '', 'يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (980, 45, 22, 'اللهمَّ اغفرْ لفلانٍ -ويُسَمِّي الميتَ-، وارفعْ درجتَهُ في المهديِّينَ، واخْلُفْهُ في عَقِبِهِ في الغابرينَ، واغفرْ لنا وله يا ربَّ العالمينَ، وافسَحْ له في قبرِهِ، ونَوِّرْ له فيهِ', 1, 'ما يقول بعد تغميض الميت. (ص166)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1628, 45, 23, 'ويقول أهلُه:', 0, 'ما يقول بعد تغميض الميت. (ص166)', '', '', 'ويقول أهله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (981, 45, 24, 'اللهمَّ اغفرْ لي وله، وأَعْقِبْني منه عُقبى حسنةً', 1, 'ما يقول بعد تغميض الميت. (ص166)', '', '', 'اللهم اغفر لي وله وأعقبني منه عقبى حسنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1629, 45, 25, 'يستحضرُ فورًا قولَ رسولِ الله ﷺ: «إنَّ الصَّبرَ عندَ الصدمةِ الأُولَى».', 0, 'ما يقول من مات له ميت. (ص167)', '', '', 'يستحضر فورا قول رسول الله «إن الصبر عند الصدمة الأولى»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1630, 45, 26, 'يحمدُ الله، ويسترجِعُ، ويقول:', 0, 'ما يقول من مات له ميت. (ص167)', '', '', 'يحمد الله ويسترجع ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (982, 45, 27, 'إنّا للهِ، وإنّا إليهِ راجعونَ، اللهمَّ أَجِرْني في مصيبتي، وأَخلِفْ لي خيرًا منها', 1, 'ما يقول من مات له ميت. (ص167)', '', '', 'إنا لله وإنا إليه راجعون اللهم أجرني في مصيبتي وأخلف لي خيرا منها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (983, 45, 28, 'إنَّ العينَ تدمعُ، والقلبَ يحزنُ، ولا نقولُ إلا ما يُرضي ربَّنا، وإنَّا بفراقِكَ يا «فلان» لمحزونون', 1, 'ما يقول من مات له ميت. (ص167)', '', '', 'إن العين تدمع والقلب يحزن ولا نقول إلا ما يرضي ربنا وإنا بفراقك يا «فلان» لمحزونون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1631, 45, 29, 'يُسَلِّم، ويقول:', 0, 'ما يقول في التعزية. (ص167)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (984, 45, 30, 'إنَّ للهِ ما أخذَ، وللهِ ما أعطى، وكلُّ شيءٍ عنده إلى أجلٍ مُسمَّى، فلتصبرْ، ولتحتسبْ', 1, 'ما يقول في التعزية. (ص167)', '', '', 'إن لله ما أخذ ولله ما أعطى وكل شيء عنده إلى أجل مسمى فلتصبر ولتحتسب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1632, 45, 31, 'يُستَحَبُّ أن يَدعوَ لها، ويُثْنِيَ عليها خيرًا، إن كانت أهلًا له، ولا يجازِف في ثنائه.', 0, 'ما يقول من مرَّت به جنازة. (ص168)', '', '', 'يستحب أن يدعو لها ويثني عليها خيرا إن كانت أهلا له ولا يجازف في ثنائه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1633, 46, 1, 'قال ﷺ: «إذا صَلَّيْتُم على الميتِ، فأخلِصُوا له الدعاءَ».', 0, 'أذكار الصلاة على الميت. (ص168)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (278, 46, 2, 'اللهمَّ اغفرْ له، وارحمْهُ، وعافِهِ، واعفُ عنهُ، وأكرِمْ نُزُلَهُ، ووَسِّعْ مُدخلَهُ، واغسِلْهُ بالماءِ والثَّلجِ والبرَدِ، ونَقِّهِ من الخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ، وأَبدِلْهُ دارًا خيرًا من دارِهِ، وأهلًا خيرًا من أهلِهِ، وزوجًا خيرًا من زوجِهِ وأدخِلْهُ الجنةَ، وأعِذْهُ من عذابِ القبرِ، ومن عذابِ النارِ', 1, 'أذكار الصلاة على الميت. (ص168)', '', '', 'اللهم اغفر له وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس وأبدله دارا خيرا من داره وأهلا خيرا من أهله وزوجا خيرا من زوجه وأدخله الجنة وأعذه من عذاب القبر ومن عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (279, 46, 3, 'اللهمَّ اغفرْ لحَيِّنا ومَيِّتِنا، وشاهدِنا وغائبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنا وأُنثانا، اللهمَّ من أحييتَهُ منَّا فأحيِهِ على الإسلامِ، ومن توفَّيتَهُ منَّا فتوفَّهُ على الإيمانِ، اللهمَّ لا تحرِمْنا أجرَهُ، ولا تُضِلَّنا بعدَهُ', 1, 'أذكار الصلاة على الميت. (ص169)', '', '', 'اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا اللهم من أحييته منا فأحيه على الإسلام ومن توفيته منا فتوفه على الإيمان اللهم لا تحرمنا أجره ولا تضلنا بعده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (280, 46, 4, 'اللهمَّ أنتَ ربُّها، وأنتَ خلقتَها، وأنتَ هديتَها للإسلامِ، وأنتَ قبضتَ روحَها، وأنتَ أعلمُ بسرِّها وعلانيتِها، جئنا شُفَعاءَ، فاغفرْ لها', 1, 'أذكار الصلاة على الميت. (ص169)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (281, 46, 5, 'اللهمَّ إنَّ فلانَ بنَ فلانٍ في ذِمَّتِكَ وحَبلِ جِوارِكَ، فَقِهِ فتنةَ القبرِ وعذابَ النارِ، وأنتَ أهلُ الوَفاءِ والحقِّ، فاغفرْ له، وارحمْهُ، إنَّكَ أنتَ الغفورُ الرحيمُ', 1, 'أذكار الصلاة على الميت. (ص169)', '', '', 'اللهم إن فلان بن فلان في ذمتك وحبل جوارك فقه فتنة القبر وعذاب النار وأنت أهل الوفاء والحق فاغفر له وارحمه إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (282, 46, 6, 'اللهمَّ عبدُكَ وابنُ أمتِكَ، احتاجَ إلى رحمتِكَ، وأنتَ غنيٌّ عن عذابِهِ، إن كانَ محسنًا؛ فزِدْ في حسناتِهِ، وإن كانَ مسيئًا؛ فتجاوَزْ عنهُ', 1, 'أذكار الصلاة على الميت. (ص169)', '', '', 'اللهم عبدك وابن أمتك احتاج إلى رحمتك وأنت غني عن عذابه إن كان محسنا فزد في حسناته وإن كان مسيئا فتجاوز عنه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1634, 46, 7, 'وكان أبو هريرةَ رضي الله عنه يدعو في صلاة الجنازة:', 0, 'أذكار الصلاة على الميت. (ص170)', '', '', 'وكان أبو هريرة رضي الله عنه يدعو في صلاة الجنازة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (283, 46, 8, 'اللهمَّ إنَّهُ عبدُكَ، وابنُ عبدِكَ، وابنُ أمتِكَ، كان يشهدُ أن لا إلهَ إلا أنتَ، وأنَّ محمدًا عبدُكَ ورسولُكَ، وأنتَ أعلمُ بهِ، اللهمَّ إن كانَ محسنًا؛ فزِدْ في حسناتِهِ، وإن كانَ مسيئًا؛ فتجاوزْ عن سيئاتِهِ، اللهمَّ لا تحرِمْنا أجرَهُ، ولا تَفْتِنَّا بعدَهُ', 1, 'أذكار الصلاة على الميت. (ص170)', '', '', 'اللهم إنه عبدك وابن عبدك وابن أمتك كان يشهد أن لا إله إلا أنت وأن محمدا عبدك ورسولك وأنت أعلم به اللهم إن كان محسنا فزد في حسناته وإن كان مسيئا فتجاوز عن سيئاته اللهم لا تحرمنا أجره ولا تفتنا بعده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1635, 46, 9, 'إذا صلَّى على الطفل قال:', 0, 'أذكار الصلاة على الميت. (ص170)', '', '', 'إذا صلى على الطفل قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (985, 46, 10, 'اللهمَّ اجعلْهُ لنا سَلَفًا وفَرَطًا وأجرًا', 1, 'أذكار الصلاة على الميت. (ص170)', '', '', 'اللهم اجعله لنا سلفا وفرطا وأجرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (986, 46, 11, 'اللهمَّ أَعِذْهُ من عذابِ القبرِ', 1, 'أذكار الصلاة على الميت. (ص170)', '', '', 'اللهم أعذه من عذاب القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1636, 46, 12, 'والسُّقْطُ يُصَلَّى عليه، ويُدْعَى لوالِدِيه بالمغفرةِ والرحمة.', 0, 'أذكار الصلاة على الميت. (ص170)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (284, 46, 13, 'باسمِ اللهِ، وعلى سُنَّةِ -أو مِلَّةِ- رسولِ اللهِ ﷺ', 1, 'ما يقول مَن يُدْخِلُ الميتَ قبرَه. (ص171)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (286, 46, 14, 'استغفِروا لأخيكُم، وسَلُوا له التثبيتَ، فإنَّهُ الآنَ يُسألُ', 1, 'ما يقول للحاضرين بعد الفراغ من دَفنِ الميت. (ص171)', '', '', 'استغفروا لأخيكم وسلوا له التثبيت فإنه الآن يسأل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (287, 46, 15, 'السلامُ عليكم دارَ قومٍ مؤمنين، وأتاكم ما تُوعَدون، وإنَّا إن شاءَ اللهُ بكم لاحِقونَ، اللهمَّ اغفرْ لأهلِ «هذه المقابرِ»', 1, 'ما يقول زائرُ القبور. (ص172)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (288, 46, 16, 'أو: السلامُ عليكم أهلَ دارِ قومٍ مؤمنين، وإنَّا وإيَّاكُم، وما تُوعَدونَ غدًا مُؤجَّلون، وإنَّا إن شاءَ اللهُ بكم لاحِقون، اللهمَّ اغفرْ لأهلِ «هذه المقابرِ»', 1, 'ما يقول زائرُ القبور. (ص172)', '', '', 'أو السلام عليكم أهل دار قوم مؤمنين وإنا وإياكم وما توعدون غدا مؤجلون وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل «هذه المقابر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (289, 46, 17, 'أو: السلامُ على أهلِ الدِّيارِ من المؤمنين والمسلمين، ويرحمُ اللهُ المُستَقدِمينَ منكم ومِنَّا والمُستأخِرين، وإنَّا إن شاءَ اللهُ بكم لاحِقون', 1, 'ما يقول زائرُ القبور. (ص172)', '', '', 'أو السلام على أهل الديار من المؤمنين والمسلمين ويرحم الله المستقدمين منكم ومنا والمستأخرين وإنا إن شاء الله بكم لاحقون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (290, 46, 18, 'أو: السلامُ عليكم أهلَ الديارِ من المؤمنين والمسلمين، وإنَّا إن شاءَ اللهُ بكم لَلاحِقونَ، أنتم لنا فَرَطٌ، ونحن لكم تَبَعٌ، أسألُ اللهَ لنا ولكُم العافيةَ', 1, 'ما يقول زائرُ القبور. (ص173)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1637, 46, 19, 'وإذا مَرَّ بِقَبْرِ كافرٍ بَشَّرَه بالنَّار.', 0, 'ما يقول زائرُ القبور. (ص173–174)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1638, 46, 20, 'وإذا مَرَّ بامْرَأةٍ تبكي عندَ قبرٍ قال لها:', 0, 'ما يقول زائرُ القبور. (ص174)', '', '', 'وإذا مر بامرأة تبكي عند قبر قال لها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (987, 46, 21, 'اتَّقي اللهَ، واصبري', 1, 'ما يقول زائرُ القبور. (ص174)', '', '', 'اتقي الله واصبري', '', '');
